import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Postulati dell'appartenenza","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/g_geometria-dello-spazio/gc/gcb.md","filePath":"lezioni/g_geometria-dello-spazio/gc/gcb.md"}`),a={name:`lezioni/g_geometria-dello-spazio/gc/gcb.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="postulati-dell-appartenenza" tabindex="-1">Postulati dell&#39;appartenenza <a class="header-anchor" href="#postulati-dell-appartenenza" aria-label="Permalink to “Postulati dell&#39;appartenenza”">​</a></h1><p>Definiscono i legami fra gli enti geometrici.</p><p>Oltre quelli già validi per il piano (che ti consiglio di <a href="./../../../f/fb/fbbb.html">ripassare</a>) valgono:</p><p>Per un punto passano infiniti piani (stella di piani).</p><p>Per una retta passano infiniti piani (fascio proprio di piani).</p><blockquote><p><strong>Nota:</strong> Da notare che, anche se i piani appartenenti alla stella di piani ed al fascio di piani sono entrambi infiniti, deve esistere qualche differenza tra loro, perché nella stella di piani ci saranno tutti quelli di un fascio proprio di piani per ciascuna retta passante per quel punto.</p><p>È la stessa differenza che c&#39;è fra i punti di una retta ed i punti di un piano: sono entrambi infiniti ma fra i due tipi di infinito deve esistere qualche differenza.</p></blockquote><p>Per tre punti non allineati passa un solo piano.</p><p>Dato uno spazio ed un piano, il piano divide lo spazio in due parti (semispazi) tali che, presi due punti nello stesso semispazio, il segmento che li unisce non taglia il piano, mentre se prendiamo due punti in semispazi opposti, il segmento che li unisce taglia il piano.</p><blockquote><p>In figura i punti <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>C</mi></mrow><annotation encoding="application/x-tex">C</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span></span></span></span> e <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>D</mi></mrow><annotation encoding="application/x-tex">D</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">D</span></span></span></span> sono nello stesso semispazio, mentre <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>A</mi></mrow><annotation encoding="application/x-tex">A</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">A</span></span></span></span> e <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>B</mi></mrow><annotation encoding="application/x-tex">B</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span></span></span></span> sono in semispazi opposti.</p></blockquote>`,9)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};